window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b11c9bbf0e8b362"]={"versions": [{"id": "FIG-9b11c9bbf0e8b362", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Schnittstellen- und Komponentendiagramm (Architekturprofil der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen dem Functional Cluster <code>Communication Management</code> (<code>ara::com</code>) und dem <code>Freshness Value Management</code> (FVM) zur Absicherung der Dienst- und PDU-Kommunikation gegen Replay-Angriffe (SecOC / Message Authentication) gemäß AUTOSAR Adaptive Platform R21-11.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>«aapFunctionalCluster»</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert das funktionale Cluster der Adaptive Platform für Inter-Process- und Inter-ECU-Kommunikation.\n</li><li>Tritt im Diagramm als Konsument/Klient der FVM-Funktionalität auf.\n</li></ul>\n</li><li><strong><code>FVM</code> (<code>«aapNativeInterface,aapPlatformExtension»</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp <code>«aapNativeInterface»</code>:</strong> Definiert eine native C++-Schnittstelle auf Plattformebene.\n</li><li><strong>Stereotyp <code>«aapPlatformExtension»</code>:</strong> Kennzeichnet die Schnittstelle als Plattform-Erweiterungspunkt (OEM- oder anbieterspezifische Implementierung, keine anwendungsseitige Standard-<code>ara::</code>-API).\n</li><li><strong>Schnittstellenmethoden:</strong>\n<ul class=\"fig-list\"><li><code>+ Initialize()</code>: Initialisiert den Zustand des FVM (z. B. Synchronisationsstatus, Trip-/Reset-Counter, Anbindung an Zeitbasen).\n</li><li><code>+ GetTxFreshness()</code>: Liefert den aktuellen Freshness-Wert (vollständig bzw. trunkiert) für den Sendevorgang zur kryptografischen MAC-Generierung.\n</li><li><code>+ GetRxFreshness()</code>: Rekonstruiert anhand des empfangenen (trunkierten) Freshness-Werts und des lokalen Zustands den vollständigen Freshness-Wert zur MAC-Verifikation.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehung:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Abhängigkeit (<code>Dependency</code> mit Stereotyp <code>«use»</code>) vom Cluster <code>Communication Management</code> auf das Interface <code>FVM</code>. Zeigt lose Kopplung via Dependency Injection / Interface-Abstraktion.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierungsphase:</strong>\n<ul class=\"fig-list\"><li>Beim Startup des Kommunikations-Stacks ruft <code>Communication Management</code> synchron <code>Initialize()</code> auf, um den internen Zustandsautomaten des FVM und etwaige Sync-Mechanismen scharfzuschalten.\n</li></ul>\n</li><li><strong>Sendepfad (TX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine Service-Instanz oder ein Socket-Binding initiiert den Versand einer authentifizierten Nachricht/PDU.\n</li><li><code>Communication Management</code> ruft synchron <code>GetTxFreshness()</code> auf.\n</li><li>Der zurückgegebene Freshness-Wert wird an das Crypto-Modul übergeben, in den Datenstrom für die CMAC-/HMAC-Berechnung eingefügt und ggf. trunkiert im Header übertragen.\n</li></ol>\n</li><li><strong>Empfangspfad (RX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine eingehende authentifizierte Nachricht trifft im Binding ein.\n</li><li><code>Communication Management</code> extrahiert den trunkierten Freshness-Wert und ruft synchron <code>GetRxFreshness()</code> auf.\n</li><li>FVM rekonstruiert den vollständigen Zähler-/Zeitstempelwert.\n</li><li>Schlägt die Rekonstruktion fehl (z. B. Out-of-Sync oder Replay-Verdacht), bricht <code>Communication Management</code> die Verarbeitung ab und verwirft die PDU.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur &amp; Integration (Platform Extension):</strong>\n<ul class=\"fig-list\"><li>Das FVM ist als <code>«aapPlatformExtension»</code> modular ausgelegt. Der Integrator muss eine konkrete FVM-Implementierung bereitstellen, die das OEM-spezifische Freshness-Protokoll (z. B. Time-Sync über gPTP/AUTOSAR Time Synchronization oder Trip-Counter-Verfahren nach SecOC) abbildet.\n</li></ul>\n</li><li><strong>Echtzeitanforderungen &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li><code>GetTxFreshness()</code> und <code>GetRxFreshness()</code> liegen direkt im synchronen Serialisierungs-/Deserialisierungspfad von <code>ara::com</code>. Die Implementierung muss zwingend reentrant, threadsicher und latenzarm (ohne blockierende I/O oder Mutex-Contention) sein.\n</li></ul>\n</li><li><strong>Kopplung an Krypto-Subsysteme:</strong>\n<ul class=\"fig-list\"><li>Das Interface übergibt die Werte typischerweise an die PDU-Router- bzw. SOME/IP-Transformator-Schicht, welche diese Werte mit dem <code>Crypto Stack</code> (<code>ara::crypto</code>) zur Signatur-/MAC-Erzeugung zusammenführt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bbfd16836bd6847c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Schnittstellen- und Komponentendiagramm (Architekturprofil der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen dem Functional Cluster <code>Communication Management</code> (<code>ara::com</code>) und dem <code>Freshness Value Management</code> (FVM) zur Absicherung der Dienst- und PDU-Kommunikation gegen Replay-Angriffe (SecOC / Message Authentication) gemäß AUTOSAR Adaptive Platform R21-11.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>«aapFunctionalCluster»</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert das funktionale Cluster der Adaptive Platform für Inter-Process- und Inter-ECU-Kommunikation.\n</li><li>Tritt im Diagramm als Konsument/Klient der FVM-Funktionalität auf.\n</li></ul>\n</li><li><strong><code>FVM</code> (<code>«aapNativeInterface,aapPlatformExtension»</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp <code>«aapNativeInterface»</code>:</strong> Definiert eine native C++-Schnittstelle auf Plattformebene.\n</li><li><strong>Stereotyp <code>«aapPlatformExtension»</code>:</strong> Kennzeichnet die Schnittstelle als Plattform-Erweiterungspunkt (OEM- oder anbieterspezifische Implementierung, keine anwendungsseitige Standard-<code>ara::</code>-API).\n</li><li><strong>Schnittstellenmethoden:</strong>\n<ul class=\"fig-list\"><li><code>+ Initialize()</code>: Initialisiert den Zustand des FVM (z. B. Synchronisationsstatus, Trip-/Reset-Counter, Anbindung an Zeitbasen).\n</li><li><code>+ GetTxFreshness()</code>: Liefert den aktuellen Freshness-Wert (vollständig bzw. trunkiert) für den Sendevorgang zur kryptografischen MAC-Generierung.\n</li><li><code>+ GetRxFreshness()</code>: Rekonstruiert anhand des empfangenen (trunkierten) Freshness-Werts und des lokalen Zustands den vollständigen Freshness-Wert zur MAC-Verifikation.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehung:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Abhängigkeit (<code>Dependency</code> mit Stereotyp <code>«use»</code>) vom Cluster <code>Communication Management</code> auf das Interface <code>FVM</code>. Zeigt lose Kopplung via Dependency Injection / Interface-Abstraktion.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierungsphase:</strong>\n<ul class=\"fig-list\"><li>Beim Startup des Kommunikations-Stacks ruft <code>Communication Management</code> synchron <code>Initialize()</code> auf, um den internen Zustandsautomaten des FVM und etwaige Sync-Mechanismen scharfzuschalten.\n</li></ul>\n</li><li><strong>Sendepfad (TX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine Service-Instanz oder ein Socket-Binding initiiert den Versand einer authentifizierten Nachricht/PDU.\n</li><li><code>Communication Management</code> ruft synchron <code>GetTxFreshness()</code> auf.\n</li><li>Der zurückgegebene Freshness-Wert wird an das Crypto-Modul übergeben, in den Datenstrom für die CMAC-/HMAC-Berechnung eingefügt und ggf. trunkiert im Header übertragen.\n</li></ol>\n</li><li><strong>Empfangspfad (RX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine eingehende authentifizierte Nachricht trifft im Binding ein.\n</li><li><code>Communication Management</code> extrahiert den trunkierten Freshness-Wert und ruft synchron <code>GetRxFreshness()</code> auf.\n</li><li>FVM rekonstruiert den vollständigen Zähler-/Zeitstempelwert.\n</li><li>Schlägt die Rekonstruktion fehl (z. B. Out-of-Sync oder Replay-Verdacht), bricht <code>Communication Management</code> die Verarbeitung ab und verwirft die PDU.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur &amp; Integration (Platform Extension):</strong>\n<ul class=\"fig-list\"><li>Das FVM ist als <code>«aapPlatformExtension»</code> modular ausgelegt. Der Integrator muss eine konkrete FVM-Implementierung bereitstellen, die das OEM-spezifische Freshness-Protokoll (z. B. Time-Sync über gPTP/AUTOSAR Time Synchronization oder Trip-Counter-Verfahren nach SecOC) abbildet.\n</li></ul>\n</li><li><strong>Echtzeitanforderungen &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li><code>GetTxFreshness()</code> und <code>GetRxFreshness()</code> liegen direkt im synchronen Serialisierungs-/Deserialisierungspfad von <code>ara::com</code>. Die Implementierung muss zwingend reentrant, threadsicher und latenzarm (ohne blockierende I/O oder Mutex-Contention) sein.\n</li></ul>\n</li><li><strong>Kopplung an Krypto-Subsysteme:</strong>\n<ul class=\"fig-list\"><li>Das Interface übergibt die Werte typischerweise an die PDU-Router- bzw. SOME/IP-Transformator-Schicht, welche diese Werte mit dem <code>Crypto Stack</code> (<code>ara::crypto</code>) zur Signatur-/MAC-Erzeugung zusammenführt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9802f103ce3cab50", "releases": ["R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Schnittstellen- und Komponentendiagramm (Architekturprofil der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen dem Functional Cluster <code>Communication Management</code> (<code>ara::com</code>) und dem <code>Freshness Value Management</code> (FVM) zur Absicherung der Dienst- und PDU-Kommunikation gegen Replay-Angriffe (SecOC / Message Authentication) gemäß AUTOSAR Adaptive Platform R21-11.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert das funktionale Cluster der Adaptive Platform für Inter-Process- und Inter-ECU-Kommunikation in seiner daemon-basierten Ausprägung (<code>daemon-based</code>).\n</li><li>Tritt im Diagramm als Konsument/Klient der FVM-Funktionalität auf.\n</li></ul>\n</li><li><strong><code>FVM</code> (<code>«aapNativeInterface,aapPlatformExtension»</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp <code>«aapNativeInterface»</code>:</strong> Definiert eine native C++-Schnittstelle auf Plattformebene.\n</li><li><strong>Stereotyp <code>«aapPlatformExtension»</code>:</strong> Kennzeichnet die Schnittstelle als Plattform-Erweiterungspunkt (OEM- oder anbieterspezifische Implementierung, keine anwendungsseitige Standard-<code>ara::</code>-API).\n</li><li><strong>Schnittstellenmethoden:</strong>\n<ul class=\"fig-list\"><li><code>+ Initialize()</code>: Initialisiert den Zustand des FVM (z. B. Synchronisationsstatus, Trip-/Reset-Counter, Anbindung an Zeitbasen).\n</li><li><code>+ GetTxFreshness()</code>: Liefert den aktuellen Freshness-Wert (vollständig bzw. trunkiert) für den Sendevorgang zur kryptografischen MAC-Generierung.\n</li><li><code>+ GetRxFreshness()</code>: Rekonstruiert anhand des empfangenen (trunkierten) Freshness-Werts und des lokalen Zustands den vollständigen Freshness-Wert zur MAC-Verifikation.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehung:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Abhängigkeit (<code>Dependency</code> mit Stereotyp <code>«use»</code>) vom Cluster <code>Communication Management</code> auf das Interface <code>FVM</code>. Zeigt lose Kopplung via Dependency Injection / Interface-Abstraktion.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierungsphase:</strong>\n<ul class=\"fig-list\"><li>Beim Startup des Kommunikations-Stacks ruft <code>Communication Management</code> synchron <code>Initialize()</code> auf, um den internen Zustandsautomaten des FVM und etwaige Sync-Mechanismen scharfzuschalten.\n</li></ul>\n</li><li><strong>Sendepfad (TX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine Service-Instanz oder ein Socket-Binding initiiert den Versand einer authentifizierten Nachricht/PDU.\n</li><li><code>Communication Management</code> ruft synchron <code>GetTxFreshness()</code> auf.\n</li><li>Der zurückgegebene Freshness-Wert wird an das Crypto-Modul übergeben, in den Datenstrom für die CMAC-/HMAC-Berechnung eingefügt und ggf. trunkiert im Header übertragen.\n</li></ol>\n</li><li><strong>Empfangspfad (RX-Sequenz):</strong>\n<ol class=\"fig-list\"><li>Eine eingehende authentifizierte Nachricht trifft im Binding ein.\n</li><li><code>Communication Management</code> extrahiert den trunkierten Freshness-Wert und ruft synchron <code>GetRxFreshness()</code> auf.\n</li><li>FVM rekonstruiert den vollständigen Zähler-/Zeitstempelwert.\n</li><li>Schlägt die Rekonstruktion fehl (z. B. Out-of-Sync oder Replay-Verdacht), bricht <code>Communication Management</code> die Verarbeitung ab und verwirft die PDU.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur &amp; Integration (Platform Extension):</strong>\n<ul class=\"fig-list\"><li>Das FVM ist als <code>«aapPlatformExtension»</code> modular ausgelegt. Der Integrator muss eine konkrete FVM-Implementierung bereitstellen, die das OEM-spezifische Freshness-Protokoll (z. B. Time-Sync über gPTP/AUTOSAR Time Synchronization oder Trip-Counter-Verfahren nach SecOC) abbildet.\n</li></ul>\n</li><li><strong>Echtzeitanforderungen &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li><code>GetTxFreshness()</code> und <code>GetRxFreshness()</code> liegen direkt im synchronen Serialisierungs-/Deserialisierungspfad von <code>ara::com</code>. Die Implementierung muss zwingend reentrant, threadsicher und latenzarm (ohne blockierende I/O oder Mutex-Contention) sein.\n</li></ul>\n</li><li><strong>Kopplung an Krypto-Subsysteme:</strong>\n<ul class=\"fig-list\"><li>Das Interface übergibt die Werte typischerweise an die PDU-Router- bzw. SOME/IP-Transformator-Schicht, welche diese Werte mit dem <code>Crypto Stack</code> (<code>ara::crypto</code>) zur Signatur-/MAC-Erzeugung zusammenführt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c24150a71eda1dc3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AUTOSAR_EXP_SWArchitecture, Figure 9.25). Es dokumentiert die statische Architekturbeziehung zwischen dem Functional Cluster Communication Management und der Schnittstelle für das Freshness Value Management (FVM) zur Absicherung der bordnetzweiten Kommunikation (z. B. SecOC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Communication Management</code>: Functional Cluster der Adaptive Platform in daemon-basierter Ausprägung (<code>daemon-based</code>), dargestellt als UML-Komponente mit Komponenten-Icon.\n</li><li><code>«aapNativeInterface, aapPlatformExtension» FVM</code>: C++-basierte native Schnittstelle und Plattform-Erweiterung mit drei öffentlichen Operationen:\n<ul class=\"fig-list\"><li><code>+ GetRxFreshness()</code>: Ermittlung des Freshness-Werts für den Empfangspfad zur Verifikation empfangener Nachrichten.\n</li><li><code>+ GetTxFreshness()</code>: Abfrage des aktuellen Freshness-Werts für den Sendepfad zur Authentisierung ausgehender PDUs.\n</li><li><code>+ Initialize()</code>: Initialisierung des internen Zustands des Freshness Value Managements.\n</li></ul>\n</li><li>Beziehung: Gerichtete Verwendungsabhängigkeit (<code>«use»</code>, gestrichelte Pfeillinie) ausgehend von <code>Communication Management</code> zur Schnittstelle <code>FVM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Initialisierung: Beim Start des Communication-Management-Daemons wird <code>Initialize()</code> aufgerufen, um Zähler, Synchronisationszustände und Schlüssel-/Epochenstrukturen des FVM aufzusetzen.\n</li><li>Sendepfad: Vor dem Übertragen einer gesicherten PDU fordert der Daemon über <code>GetTxFreshness()</code> den aktuellen Sende-Freshness-Wert an, um diesen in den Authentifizierungs-Tag (z. B. MAC-Berechnung) einzubringen und ggf. anteilig in der Nachricht zu übertragen.\n</li><li>Empfangspfad: Bei Empfang einer gesicherten PDU ruft der Daemon <code>GetRxFreshness()</code> auf, um anhand der übermittelten Teilinformationen den vollständigen Freshness-Wert für die Verifikation der Nachricht und die Abwehr von Replay-Angriffen zu rekonstruieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>«aapPlatformExtension»</code>: Kennzeichnet die FVM-Schnittstelle als Plattform-Erweiterung außerhalb des Kerns anwendungsspezifischer ARA-Schnittstellen; die Implementierung erfolgt plattformspezifisch bzw. OEM-spezifisch.\n</li><li><code>«aapNativeInterface»</code>: Definiert die Schnittstelle als native C++-API (Direct Call / Library Linkage) innerhalb des Prozesses ohne Overhead durch Service-Proxies oder IPC-Serialisierung.\n</li><li><code>daemon-based</code>: Communication Management läuft als POSIX-Hintergrunddienst (Daemon); der Zugriff auf FVM erfolgt aus dem Kontext dieses zentralen Kommunikationsprozesses.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d0985b2d386d07f3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AUTOSAR_EXP_SWArchitecture, Figure 9.25). Es visualisiert die Schnittstellenbeziehung zwischen dem Functional Cluster Time Synchronization und der Schnittstelle für das Freshness Value Management (FVM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Time Synchronization</code>: Functional Cluster der Adaptive Platform in daemon-basierter Implementierung (<code>daemon-based</code>), dargestellt als UML-Komponente mit Komponenten-Icon.\n</li><li><code>«aapNativeInterface, aapPlatformExtension» FVM</code>: C++-basierte native Schnittstelle und Plattform-Erweiterung mit drei öffentlichen Operationen:\n<ul class=\"fig-list\"><li><code>+ GetRxFreshness()</code>: Bereitstellung von Freshness-Informationen für die Verifikation empfangener zeitbezogener Nachrichten.\n</li><li><code>+ GetTxFreshness()</code>: Ermittlung von Freshness-Werten für auszusendende Zeitnachrichten.\n</li><li><code>+ Initialize()</code>: Initialisierung des FVM-Moduls.\n</li></ul>\n</li><li>Beziehung: Gerichtete Verwendungsabhängigkeit (<code>«use»</code>, gestrichelte Pfeillinie) von <code>Time Synchronization</code> auf die Schnittstelle <code>FVM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Initialisierung: Beim Hochfahren des Time-Synchronization-Daemons erfolgt der Aufruf von <code>Initialize()</code>, um die Frischewert-Verwaltung zu instanziieren und zu initialisieren.\n</li><li>Zeitnachrichten-Sendepfad: Vor dem Versenden von zeitsynchronisierenden Nachrichten (z. B. im Rahmen gesicherter Zeitverteilungsprotokolle) ruft der Time-Synchronization-Daemon <code>GetTxFreshness()</code> auf, um einen aktuellen Frischewert für die Signatur-/MAC-Generierung zu beziehen.\n</li><li>Zeitnachrichten-Empfangspfad: Eintreffende Zeitnachrichten werden über <code>GetRxFreshness()</code> validiert, um Replay-Angriffe auf Zeitprotokolle auszuschließen und die Aktualität der Zeitsynchronisationsdaten sicherzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>«aapPlatformExtension»</code>: FVM ist als plattformspezifische Erweiterung klassifiziert, die hersteller- oder projektspezifisch implementiert werden kann.\n</li><li><code>«aapNativeInterface»</code>: Schreibt eine prozesslokale C++-Schnittstellenanbindung ohne IPC- oder Service-Proxy/Skeleton-Schicht vor.\n</li><li><code>daemon-based</code>: Time Synchronization ist als Daemon-Prozess implementiert. Die Modellierung weist Time Synchronization als Konsumenten der FVM-Schnittstelle aus; Integratoren müssen prüfen, ob die Absicherung von Zeitprotokollen (z. B. Securing PTP / IEEE 802.1AS) über diese FVM-Anbindung realisiert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3dddfc7dfa074355", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponenten- und Klassendiagramm im Kontext der AUTOSAR Adaptive Platform (AUTOSAR_EXP_SWArchitecture, Figure 9.25). Es visualisiert die Schnittstellenbeziehung zwischen dem Functional Cluster Time Synchronization und der Schnittstelle für das Freshness Value Management (FVM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Time Synchronization</code>: Functional Cluster der Adaptive Platform in daemon-basierter Implementierung (<code>daemon-based</code>), dargestellt als UML-Komponente mit Komponenten-Icon.\n</li><li><code>«aapNativeInterface, aapPlatformExtension» FVM</code>: C++-basierte native Schnittstelle und Plattform-Erweiterung mit drei öffentlichen Operationen:\n<ul class=\"fig-list\"><li><code>+ GetRxFreshness()</code>: Bereitstellung von Freshness-Informationen für die Verifikation empfangener zeitbezogener Nachrichten.\n</li><li><code>+ GetTxFreshness()</code>: Ermittlung von Freshness-Werten für auszusendende Zeitnachrichten.\n</li><li><code>+ Initialize()</code>: Initialisierung des FVM-Moduls.\n</li></ul>\n</li><li>Beziehung: Gerichtete Verwendungsabhängigkeit (<code>«use»</code>, gestrichelte Pfeillinie) von <code>Time Synchronization</code> auf die Schnittstelle <code>FVM</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Initialisierung: Beim Hochfahren des Time-Synchronization-Daemons erfolgt der Aufruf von <code>Initialize()</code>, um die Frischewert-Verwaltung zu instanziieren und zu initialisieren.\n</li><li>Zeitnachrichten-Sendepfad: Vor dem Versenden von zeitsynchronisierenden Nachrichten (z. B. im Rahmen gesicherter Zeitverteilungsprotokolle) ruft der Time-Synchronization-Daemon <code>GetTxFreshness()</code> auf, um einen aktuellen Frischewert für die Signatur-/MAC-Generierung zu beziehen.\n</li><li>Zeitnachrichten-Empfangspfad: Eintreffende Zeitnachrichten werden über <code>GetRxFreshness()</code> validiert, um Replay-Angriffe auf Zeitprotokolle auszuschließen und die Aktualität der Zeitsynchronisationsdaten sicherzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>«aapPlatformExtension»</code>: FVM ist als plattformspezifische Erweiterung klassifiziert, die hersteller- oder projektspezifisch implementiert werden kann.\n</li><li><code>«aapNativeInterface»</code>: Schreibt eine prozesslokale C++-Schnittstellenanbindung ohne IPC- oder Service-Proxy/Skeleton-Schicht vor.\n</li><li><code>daemon-based</code>: Time Synchronization ist als Daemon-Prozess implementiert. Die Modellierung weist Time Synchronization als Konsumenten der FVM-Schnittstelle aus; Integratoren müssen prüfen, ob die Absicherung von Zeitprotokollen (z. B. Securing PTP / IEEE 802.1AS) über diese FVM-Anbindung realisiert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9b11c9bbf0e8b362", "to": "FIG-bbfd16836bd6847c", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bbfd16836bd6847c", "to": "FIG-9802f103ce3cab50", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>«aapFunctionalCluster»</code>):</strong> Die Komponentenbeschriftung wurde um den Zusatz <code>daemon-based</code> ergänzt.\n</li></ul>"}]};
